WITH flattened AS (SELECT id, EXPLODE(tier_limits) AS val FROM price_tiers) SELECT CASE WHEN val >= 67 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS event_count, PERCENTILE_APPROX(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles, APPROX_PERCENTILE(val, 0.95) AS val_p95 FROM flattened GROUP BY CASE WHEN val >= 67 THEN 'LARGE' ELSE 'SMALL' END ORDER BY val_tier DESC NULLS LAST
